                Skip out-of-bounds data but still consume the bytes.
              */
              for (i=0; i <= (ssize_t) operand; i++)
                (void) ReadBlobByte(image);
              if (operand & 0x01)
                (void) ReadBlobByte(image);
              x+=operand+1;
              break;
            }
          offset=((image->rows-y-1)*image->columns*number_planes)+x*
            number_planes+plane;
          operand++;
          if ((offset >= pixel_info_length) ||
              ((size_t) operand*number_planes > pixel_info_length-offset))
            {
              if (number_colormaps != 0)
                colormap=(unsigned char *) RelinquishMagickMemory(colormap);
              pixel_info=RelinquishVirtualMemory(pixel_info);
              ThrowReaderException(CorruptImageError,"UnableToReadImageData");
            }
          p=pixels+offset;
          for (i=0; i < (ssize_t) operand; i++)
          {
            pixel=(unsigned char) ReadBlobByte(image);
            if ((y >= 0) && (y < (ssize_t) image->rows) &&
                ((x+i) >= 0) && ((x+i) < (ssize_t) image->columns))
              *p=pixel;
            p+=number_planes;
          }
          if (operand & 0x01)
            (void) ReadBlobByte(image);
          x+=operand;
          break;
        }
        case RunDataOp:
        {
          operand=ReadBlobByte(image);
          if (opcode & 0x40)
            operand=ReadBlobLSBSignedShort(image);
          pixel=(unsigned char) ReadBlobByte(image);
          (void) ReadBlobByte(image);
          if (operand < 0)
            {
              if (number_colormaps != 0)
                colormap=(unsigned char *) RelinquishMagickMemory(colormap);
              pixel_info=RelinquishVirtualMemory(pixel_info);
              ThrowReaderException(CorruptImageError,"UnableToReadImageData");
            }
          operand++;
          if ((y < 0) || ((size_t) y >= image->rows) || (x < 0) ||
              ((size_t) x >= image->columns) || ((size_t) plane >= number_planes))
            {
              x+=operand;
              break;
            }
          offset=((image->rows-y-1)*image->columns*number_planes)+x*
            number_planes+plane;
          if ((offset >= pixel_info_length) ||
              ((size_t) operand*number_planes > pixel_info_length-offset))
            {
              if (number_colormaps != 0)
                colormap=(unsigned char *) RelinquishMagickMemory(colormap);
              pixel_info=RelinquishVirtualMemory(pixel_info);
              ThrowReaderException(CorruptImageError,"UnableToReadImageData");
            }
          p=pixels+offset;
          for (i=0; i < (ssize_t) operand; i++)
          {
            if ((y >= 0) && (y < (ssize_t) image->rows) &&
                ((x+i) >= 0) && ((x+i) < (ssize_t) image->columns))
              *p=pixel;
            p+=number_planes;
          }
          x+=operand;
          break;
        }
        default:
          break;
      }
      opcode=ReadBlobByte(image);
    } while (((opcode & 0x3f) != EOFOp) && (opcode != EOF));
